  choices = $EXPL$["The general ledger balances recorded by the accounting department","Square footage of retail space used to estimate expected rental revenue","Bank statements showing cash receipts and disbursement activity","Accounts receivable confirmations returned by third-party customers"]$EXPL$::jsonb,
